  variant?: 'card' | 'button';
  // 'center' centers the card (default, for full-width use). 'start' left-aligns
  // it so its edge matches surrounding headings, e.g. inside a content column.
  align?: 'center' | 'start';
}

const {
  eventId,
  heading,
  body,
  scheduleDetails,
  buttonLabel = 'Register Now',
  variant = 'card',
  align = 'center',
} = Astro.props as Props;

const isValidEventId = /^[a-f0-9]{24}$/i.test(eventId);
// Public Corsizio event registration page. Same URL pattern used by the course
// workshop links elsewhere on the site, so the button can reuse the site's
// orange register-button styling rather than Corsizio's embedded iframe.
const registrationUrl = `https://agilepainrelief.corsizio.com/event/${eventId}`;
// Matches the orange register buttons used on the course blocks.
const buttonClasses =
  'inline-flex items-center gap-2 rounded-lg border-2 border-orange-500 bg-orange-100 px-5 py-2.5 font-bold text-black transition-colors hover:bg-orange-200';
---

{
  variant === 'button' ? (
    <div class="not-prose">
      {isValidEventId ? (
        <a
          href={registrationUrl}
          target="_blank"
          rel="noopener noreferrer"
          class={buttonClasses}
        >
          {buttonLabel}
        </a>
      ) : (
        <p class="text-sm italic">
          Registration opens soon. Email{' '}
          <a href="mailto:mark@agilepainrelief.com" class="text-orange-600">
            mark@agilepainrelief.com
          </a>{' '}
          to be notified.
        </p>
      )}
    </div>
  ) : (
    <section class="w-full">
      <div class="container mx-auto">
        <div
          class={`not-prose ${align === 'start' ? '' : 'mx-auto'} max-w-3xl rounded-2xl border-2 border-blue-200 bg-white p-4 md:p-6`}
        >
          {heading && (
            <SectionHeading
              headingType={HeadingType.h2}
              heading={heading}
              body={body}
            />
          )}
          {!heading && body && (
            <p
              class="xs:text-lg max-w-2xl text-base lg:text-xl"
              set:html={body}
            />
          )}
          {scheduleDetails && scheduleDetails.length > 0 && (
            <ul class="mt-4 list-disc space-y-2 pl-6 text-base lg:text-lg">
              {scheduleDetails.map((detail) => (
                <li set:html={detail} />
              ))}
            </ul>
          )}
          <div class={heading || body || scheduleDetails ? 'mt-6' : ''}>
            {isValidEventId ? (
              <a
                href={registrationUrl}
                target="_blank"
                rel="noopener noreferrer"
                class={buttonClasses}
              >
                {buttonLabel}
              </a>
            ) : (
              <p class="text-base italic">
                Registration opens soon. Email{' '}
                <a
                  href="mailto:mark@agilepainrelief.com"
                  class="text-orange-600"
                >
                  mark@agilepainrelief.com
                </a>{' '}
                to be notified.
              </p>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}
