import type { CourseType } from '@/utils/types/types';
import { parse, format, isValid } from 'date-fns';

interface Props {
  course: CourseType;
}

const { course } = Astro.props;

// Only generate structured data for workshops with future dates or those that can be joined anytime
const workshopsToInclude = course.data.workshops.workshops.filter(
  (workshop) => {
    // Include workshops that can be joined anytime
    const isJoinAnytime =
      workshop.date.toLowerCase().includes('anytime') ||
      workshop.date.toLowerCase().includes('join any') ||
      workshop.date.toLowerCase().includes('register anytime') ||
      workshop.date.toLowerCase().includes('none currently');

    if (isJoinAnytime) return true;

    // Try to parse the date from various workshop date formats
    let workshopDate;

    // Format: "April 28-29, 2025"
    const dateMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})/
    );

    // Format: "May 27-30, 2025 (half-days)"
    const dateWithParenthesisMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})\s+\(/
    );

    if (dateMatch) {
      const [_, month, day, year] = dateMatch;
      workshopDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
    } else if (dateWithParenthesisMatch) {
      const [_, month, day, year] = dateWithParenthesisMatch;
      workshopDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
    }

    // Include if we can't parse the date or if the date is in the future
    return (
      !workshopDate || !isValid(workshopDate) || workshopDate >= new Date()
    );
  }
);

// Determine price range based on course type
let priceValue = 1495; // Default price
let priceCurrency = 'CAD';

