import fs from 'fs';
import path from 'path';

const ROOT = path.resolve(__dirname, '..');
const API = 'https://api.corsizio.com/v1';

/** Hand-parse the root .env (it's a named pipe, so read it exactly once). */
function loadKey(): string {
  const raw = fs.readFileSync(path.join(ROOT, '.env'), 'utf-8');
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    if (trimmed.slice(0, eq).trim() === 'CORSIZIO') {
      return trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
    }
  }
  throw new Error('CORSIZIO not found in root .env');
}

const KEY = loadKey();

async function get(pathname: string): Promise<{ status: number; body: unknown }> {
  const res = await fetch(`${API}${pathname}`, {
    headers: { Authorization: `Bearer ${KEY}` },
  });
  const text = await res.text();
  let body: unknown = text;
  try {
    body = JSON.parse(text);
  } catch {
    /* leave as text so an HTML error page is still visible */
  }
  return { status: res.status, body };
}

function dump(name: string, data: unknown): void {
  const file = path.join(ROOT, 'temp', `corsizio-${name}.json`);
