import type { CourseType, PageType } from '@/utils/types/types';

import { HeadingType, TextAlignment } from '@/utils/formattingEnums';
import SectionHeading from '@/components/global/section-heading.astro';
import CoursesTabs from '@/components/global/courses-cta/courses-tabs';

interface Props {
  courses: CourseType[];
  pages: PageType[];
