/**
 * Pull the course schedule from Corsizio and write shared/course-schedule.json.
 *
 * Corsizio is the source of truth for WHEN a public course runs and WHAT it
 * costs. This script is the only thing that talks to their API for listings;
 * everything downstream (course pages, the "Get Certified" block, JSON-LD, the
 * newsletter's Upcoming Courses list) reads the generated file.
 *
 * The generated file is committed on purpose. It lives in shared/, so writing
 * it triggers a Netlify rebuild on push, and a Corsizio outage can never take a
 * deploy down. It also gives us a git history of schedule changes.
 *
 *   npm run sync-courses            # write the file
 *   npm run sync-courses -- --dry-run   # print what would change, write nothing
 *
 * Needs CORSIZIO (the API secret access key) in the repo-root .env.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUTPUT_PATH = path.join(ROOT, 'shared', 'course-schedule.json');
const API = 'https://api.corsizio.com/v1';

// --- Corsizio category -> course ------------------------------------------
//
// Every Corsizio event carries exactly one category, and the category ids are
// stable, so this table is the whole mapping: no matching on event names, which
// change whenever Mark retitles a workshop.
//
// `slug` is the src/content/courses/ directory name. `null` means "real course,
// deliberately not a course-collection page" — currently only the AI Tsunami,
// which is a marketing page with its own hand-written schedule prose.
//
// A category id that is NOT in this table is reported loudly by the sync: it
// means a new kind of course exists in Corsizio and nothing on the site will
// show it until someone adds a row here.

interface CourseMapping {
  slug: string | null;
  /** Display name for the newsletter's Upcoming Courses list. */
  name: string;
}

const CATEGORY_TO_COURSE: Record<string, CourseMapping> = {
  '67e30b6100cd6ddccedcc2c1': {
    slug: 'certified-scrummaster-csm-training',
    name: 'Certified ScrumMaster (CSM)',
  },
  '67e4270400cd6ddccefef17c': {
    slug: 'certified-scrum-product-owner-cspo-training',
    name: 'Certified Scrum Product Owner (CSPO)',
  },
  '67e4271d00cd6ddccefef4db': {
    slug: 'advanced-certified-scrummaster-acsm-training',
    name: 'Advanced Certified ScrumMaster (A-CSM)',
  },
  '67fd4bae00cd6ddcceb14a06': {
    slug: 'certified-scrum-professional-scrummaster-csp-sm-training',
    name: 'Certified Scrum Professional - ScrumMaster (CSP-SM)',
  },
  '68f253e18289735f6334a11e': {
    slug: 'scrum-better-with-kanban',
    name: 'Scrum Better with Kanban',
  },
  // Only the Technical track is scheduled, so Corsizio has one CSD category and
  // it maps to the Technical page. The Nontechnical page therefore never gets
  // events and always renders the "contact us" placeholder, which is correct.
  '69cd8eb84fa9204f41054cc2': {
    slug: 'certified-scrum-developer-training-csd-technical',
    name: 'Certified Scrum Developer (CSD)',
  },
  '6a106e4c8bc748bdca8e91bc': {
    slug: null, // Surviving the AI Tsunami — a page, not a course collection entry
    name: 'Surviving the AI Tsunami',
  },
};

// Corsizio labels every online event "In-person Online". Normalise to the
// wording the site has always used.
function normaliseLocation(raw: string | undefined): string {
  if (!raw) return 'Live Online';
  return /online|virtual/i.test(raw) ? 'Live Online' : raw;
}

// --- Corsizio types (only the fields we consume) --------------------------

interface CorsizioPrice {
  price: number;
  label?: string;
  earlyPrice: number | null;
  earlyBefore: string | null;
}

interface CorsizioEvent {
  id: string;
  name: string;
  startDate: string; // ISO 8601, UTC
  endDate: string; // ISO 8601, UTC
  displayDate: string;
  timeZone: string; // IANA, e.g. America/Toronto
  location?: string;
  priceFrom?: number;
  priceTo?: number;
  prices?: CorsizioPrice[];
  currency?: string;
  pageUrl: string;
  registrationCloseDate?: string | null;
  categories?: { id: string; label: string }[];
}

interface EventsListResponse {
  paging: { page: number; limit: number; count: number; more: boolean };
  list: CorsizioEvent[];
}

// --- Generated file shape -------------------------------------------------

export interface ScheduledWorkshop {
  eventId: string;
  /** ISO 8601 UTC, first day's start. */
  startDate: string;
  /** ISO 8601 UTC, last day's end. */
  endDate: string;
  /** IANA timezone the course is run in. */
  timeZone: string;
  /** e.g. "August 11-14, 2026" */
  dateLabel: string;
  /** Daily start-end, e.g. "9:00 AM - 1:00 PM EDT" */
  timeLabel: string;
  /** Days spanned, inclusive. */
  numberOfDays: number;
  location: string;
  url: string;
  priceFrom: number;
  priceTo: number;
  currency: string;
  registrationCloseDate: string | null;
}

interface CourseSchedule {
  /** Display name, for consumers with no access to the content collection. */
  name: string;
  workshops: ScheduledWorkshop[];
}

interface ScheduleFile {
  generatedAt: string;
  courses: Record<string, CourseSchedule>;
}

// --- Date formatting, in the event's own timezone -------------------------
//
// startDate/endDate are UTC instants; the course runs in `timeZone`. Every
// label and the day count must be computed in that zone, or a 9am Toronto class
// can round to the wrong calendar day.

/** Calendar parts (y/m/d/h/min) of an instant, as seen in `timeZone`. */
function partsIn(iso: string, timeZone: string) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    hour12: false,
  });
  const parts = Object.fromEntries(
    fmt.formatToParts(new Date(iso)).map((p) => [p.type, p.value])
  );
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
  };
}

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

/** "August 11-14, 2026", "September 3, 2026", "August 31 - September 1, 2026" */
function buildDateLabel(startIso: string, endIso: string, timeZone: string): string {
  const s = partsIn(startIso, timeZone);
  const e = partsIn(endIso, timeZone);

  if (s.year === e.year && s.month === e.month) {
    const days = s.day === e.day ? `${s.day}` : `${s.day}-${e.day}`;
    return `${MONTHS[s.month - 1]} ${days}, ${s.year}`;
  }
  if (s.year === e.year) {
    return `${MONTHS[s.month - 1]} ${s.day} - ${MONTHS[e.month - 1]} ${e.day}, ${s.year}`;
  }
  return `${MONTHS[s.month - 1]} ${s.day}, ${s.year} - ${MONTHS[e.month - 1]} ${e.day}, ${e.year}`;
}

/** Timezone abbreviation as of a given instant, e.g. "EDT". */
function tzAbbrev(iso: string, timeZone: string): string {
  const fmt = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'short' });
  return fmt.formatToParts(new Date(iso)).find((p) => p.type === 'timeZoneName')?.value ?? '';
}

function format12h(hour: number, minute: number): string {
  const period = hour < 12 ? 'AM' : 'PM';
  const h = hour % 12 === 0 ? 12 : hour % 12;
  return `${h}:${String(minute).padStart(2, '0')} ${period}`;
}

/**
 * "9:00 AM - 1:00 PM EDT" — the daily class times.
 *
 * startDate carries the FIRST day's start and endDate the LAST day's end, so
 * for the courses we run (same hours every day) this is the daily schedule.
 * It would be wrong for an event whose days have different hours; Corsizio
 * models those with breakdownDates, which none of our courses use.
 */
function buildTimeLabel(startIso: string, endIso: string, timeZone: string): string {
  const s = partsIn(startIso, timeZone);
  const e = partsIn(endIso, timeZone);
  return `${format12h(s.hour, s.minute)} - ${format12h(e.hour, e.minute)} ${tzAbbrev(endIso, timeZone)}`;
}

/** Calendar days spanned, inclusive, counted in the event's timezone. */
function countDays(startIso: string, endIso: string, timeZone: string): number {
  const s = partsIn(startIso, timeZone);
  const e = partsIn(endIso, timeZone);
  const startUtc = Date.UTC(s.year, s.month - 1, s.day);
  const endUtc = Date.UTC(e.year, e.month - 1, e.day);
  return Math.round((endUtc - startUtc) / 86_400_000) + 1;
}

// --- Fetch ----------------------------------------------------------------

/** Read CORSIZIO from the repo-root .env (a named pipe: read it exactly once). */
function loadKey(): string {
  const envPath = path.join(ROOT, '.env');
  let raw: string;
  try {
    raw = fs.readFileSync(envPath, 'utf-8');
  } catch (err) {
    throw new Error(`Could not read ${envPath}: ${String(err)}`);
  }
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    if (trimmed.slice(0, eq).trim() === 'CORSIZIO') {
      return trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
    }
  }
  throw new Error('CORSIZIO not set in the repo-root .env');
}

async function fetchAllEvents(key: string): Promise<CorsizioEvent[]> {
  const events: CorsizioEvent[] = [];
  let page = 1;
  for (;;) {
    const url =
      `${API}/events?status=published&limit=100&page=${page}` +
      `&order=startDate&expand=filters`;
    const res = await fetch(url, { headers: { Authorization: `Bearer ${key}` } });
    if (!res.ok) {
      throw new Error(`Corsizio GET /events failed: HTTP ${res.status} ${await res.text()}`);
    }
    const body = (await res.json()) as EventsListResponse;
    events.push(...body.list);
    if (!body.paging.more) return events;
    page += 1;
  }
}

// --- Build ----------------------------------------------------------------

function toWorkshop(e: CorsizioEvent): ScheduledWorkshop {
  const prices = (e.prices ?? []).map((p) => p.price);
  return {
    eventId: e.id,
    startDate: e.startDate,
    endDate: e.endDate,
    timeZone: e.timeZone,
    dateLabel: buildDateLabel(e.startDate, e.endDate, e.timeZone),
    timeLabel: buildTimeLabel(e.startDate, e.endDate, e.timeZone),
    numberOfDays: countDays(e.startDate, e.endDate, e.timeZone),
    location: normaliseLocation(e.location),
    url: e.pageUrl,
    priceFrom: e.priceFrom ?? Math.min(...prices),
    priceTo: e.priceTo ?? Math.max(...prices),
    currency: e.currency ?? 'CAD',
    registrationCloseDate: e.registrationCloseDate ?? null,
  };
}

function buildSchedule(events: CorsizioEvent[], now: Date): ScheduleFile {
  const courses: Record<string, CourseSchedule> = {};

  // Every mapped course gets an entry, even with no events: consumers then
  // render the "none currently scheduled" placeholder from a real empty list
  // rather than having to treat a missing key as a special case.
  for (const mapping of Object.values(CATEGORY_TO_COURSE)) {
    if (mapping.slug) courses[mapping.slug] = { name: mapping.name, workshops: [] };
  }

  const unknown = new Map<string, string>();

  for (const event of events) {
    const category = event.categories?.[0];
    if (!category) {
      console.warn(`  ! no category, skipped: ${event.name} (${event.id})`);
      continue;
    }
    const mapping = CATEGORY_TO_COURSE[category.id];
    if (!mapping) {
      unknown.set(category.id, category.label);
      continue;
    }
    if (!mapping.slug) continue; // deliberately not a course page
    if (new Date(event.startDate) < now) continue; // already run

    courses[mapping.slug].workshops.push(toWorkshop(event));
  }

  for (const list of Object.values(courses)) {
    list.workshops.sort((a, b) => a.startDate.localeCompare(b.startDate));
  }

  if (unknown.size > 0) {
    console.warn('\n  ! Corsizio categories with no mapping (their events are INVISIBLE on the site):');
    for (const [id, label] of unknown) {
      console.warn(`      ${id}  ${label}`);
    }
    console.warn('    Add a row to CATEGORY_TO_COURSE in scripts/corsizio-sync.ts.\n');
  }

  return {
    generatedAt: now.toISOString(),
    courses: Object.fromEntries(
      Object.keys(courses).sort().map((slug) => [slug, courses[slug]])
    ),
  };
}

// --- Main -----------------------------------------------------------------

async function main(): Promise<void> {
  const dryRun = process.argv.includes('--dry-run');

  const events = await fetchAllEvents(loadKey());
  console.log(`Fetched ${events.length} published events from Corsizio.`);

  const schedule = buildSchedule(events, new Date());

  let scheduled = 0;
  for (const [slug, course] of Object.entries(schedule.courses)) {
    const { workshops } = course;
    scheduled += workshops.length;
    const summary =
      workshops.length === 0
        ? 'none scheduled'
        : workshops.map((w) => `${w.dateLabel} (${w.timeLabel})`).join(', ');
    console.log(`  ${slug}: ${summary}`);
  }
  console.log(`\n${scheduled} upcoming workshop(s) across ${Object.keys(schedule.courses).length} courses.`);

  if (dryRun) {
    console.log('\n--dry-run: shared/course-schedule.json not written.');
    return;
  }

  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify(schedule, null, 2)}\n`);
  console.log(`\nWrote ${path.relative(ROOT, OUTPUT_PATH)}`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

