/**
 * Course schedule lookup.
 *
 * The schedule is generated from Corsizio by `npm run sync-courses` (see
 * scripts/corsizio-sync.ts) into shared/course-schedule.json. Nothing in the
 * site hand-maintains workshop dates: course frontmatter owns the marketing
 * copy, Corsizio owns the dates and prices.
 */

import schedule from '../../shared/course-schedule.json';

export interface ScheduledWorkshop {
  eventId: string;
  /** ISO 8601 UTC, first day's start. */
  startDate: string;
  /** ISO 8601 UTC, last day's end. */
  endDate: string;
  /** IANA timezone the course runs in. */
  timeZone: string;
  /** e.g. "August 11-14, 2026" */
  dateLabel: string;
  /** Daily start-end, e.g. "9:00 AM - 1:00 PM EDT" */
  timeLabel: string;
  numberOfDays: number;
  location: string;
  url: string;
  priceFrom: number;
  priceTo: number;
  currency: string;
  registrationCloseDate: string | null;
}

/**
 * Upcoming workshops for a course, by content-collection slug.
 *
 * Returns an empty array both for a course with nothing scheduled and for a
 * slug Corsizio has no category for (the CSD Nontechnical page, which isn't
 * currently run). Callers render the same "contact us" placeholder either way,
 * so the two cases don't need distinguishing.
 */
export function workshopsFor(slug: string): ScheduledWorkshop[] {
  const courses = schedule.courses as Record<string, { workshops: ScheduledWorkshop[] }>;
  return courses[slug]?.workshops ?? [];
}

/** When the schedule was last pulled from Corsizio (ISO 8601). */
export const scheduleGeneratedAt: string = schedule.generatedAt;

