import type { ScheduledWorkshop } from '@/lib/courses';
import { ArrowRight } from 'lucide-react';
import clsx from 'clsx';

interface WorkshopButtonsProps {
  workshops: ScheduledWorkshop[];
  variant?: 'column' | 'grid';
}

export default function WorkshopButtons({
  workshops,
  variant = 'column',
}: WorkshopButtonsProps) {
  // A course with nothing scheduled used to be a hand-typed "None Currently
  // Scheduled" row in frontmatter, which went stale silently. It's now the
  // absence of Corsizio events, so the fallback belongs here.
  if (workshops.length === 0) {
    return (
      <a
        href="/contact-us/"
        className="relative rounded-lg border-2 border-blue-300 bg-blue-50 px-4 py-2 text-black transition-colors hover:bg-blue-100"
      >
        <strong className="text-lg">None currently scheduled</strong>
        <p>Contact us to be notified</p>
        <ArrowRight className="absolute right-1 bottom-1 -rotate-45 text-blue-500" />
      </a>
    );
  }

  return (
    <div
      className={clsx(
        variant === 'column' && 'flex flex-col gap-4',
        variant === 'grid' && 'grid grid-cols-1 gap-4 sm:grid-cols-2'
      )}
    >
      {workshops.map((workshop) => (
        <a
          key={workshop.eventId}
          href={workshop.url}
          target="_blank"
          rel="noopener noreferrer"
          className="relative rounded-lg border-2 border-orange-500 bg-orange-100 px-4 py-2 text-black transition-colors hover:bg-orange-200"
        >
          <strong className="text-lg">{workshop.dateLabel}</strong>
          <p>{workshop.location}</p>
          <p className="text-sm">{workshop.timeLabel}</p>
          <ArrowRight className="absolute right-1 bottom-1 -rotate-45 text-orange-600" />
        </a>
      ))}
    </div>
  );
}

