import type { CourseType } from '@/utils/types/types';
import { ArrowRight } from 'lucide-react';
import clsx from 'clsx';
interface WorkshopButtonsProps {
  workshop: Pick<CourseType['data']['workshops'], 'workshops'>;
  variant?: 'column' | 'grid';
}

export default function WorkshopButtons({
  workshop,
  variant = 'column',
}: WorkshopButtonsProps) {
  return (
    <div
      className={clsx(
        variant === 'column' && 'flex flex-col gap-4',
        variant === 'grid' && 'grid grid-cols-1 gap-4 sm:grid-cols-2'
      )}
    >
      {workshop.workshops.map((workshop, index) => (
        <a
          key={index}
          href={workshop.url}
          target="_blank"
          rel="noopener noreferrer"
          className="relative rounded-lg border-2 border-orange-500 bg-orange-100 px-4 py-2 text-black transition-colors hover:bg-orange-200"
        >
          <strong className="text-lg">{workshop.date}</strong>
          <p>{workshop.location}</p>
          <ArrowRight className="absolute right-1 bottom-1 -rotate-45 text-orange-600" />
        </a>
