---
import type { CourseType } from '@/utils/types/types';
import { parse, format, isValid } from 'date-fns';

interface Props {
  course: CourseType;
}

const { course } = Astro.props;

// Only generate structured data for workshops with future dates or those that can be joined anytime
const workshopsToInclude = course.data.workshops.workshops.filter(
  (workshop) => {
    // Include workshops that can be joined anytime
    const isJoinAnytime =
      workshop.date.toLowerCase().includes('anytime') ||
      workshop.date.toLowerCase().includes('join any') ||
      workshop.date.toLowerCase().includes('register anytime') ||
      workshop.date.toLowerCase().includes('none currently');

    if (isJoinAnytime) return true;

    // Try to parse the date from various workshop date formats
    let workshopDate;

    // Format: "April 28-29, 2025"
    const dateMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})/
    );

    // Format: "May 27-30, 2025 (half-days)"
    const dateWithParenthesisMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})\s+\(/
    );

    if (dateMatch) {
      const [_, month, day, year] = dateMatch;
      workshopDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
    } else if (dateWithParenthesisMatch) {
      const [_, month, day, year] = dateWithParenthesisMatch;
      workshopDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
    }

    // Include if we can't parse the date or if the date is in the future
    return (
      !workshopDate || !isValid(workshopDate) || workshopDate >= new Date()
    );
  }
);

// Determine price range based on course type
let priceValue = 1495; // Default price
let priceCurrency = 'CAD';

// Set price based on course shortName
if (course.data.shortName) {
  const shortName = course.data.shortName.toLowerCase();
  if (shortName === 'csm') {
    priceValue = 995;
  } else if (shortName === 'cspo') {
    priceValue = 995;
  } else if (shortName === 'a-csm') {
    priceValue = 1495;
  } else if (shortName === 'csp-sm') {
    priceValue = 1995;
  } else if (shortName.includes('csd')) {
    priceValue = 1195;
  }
}

// Generate structured data for each workshop
const eventsStructuredData = workshopsToInclude.map((workshop) => {
  // Extract location information
  const isVirtual =
    workshop.location.toLowerCase().includes('virtual') ||
    workshop.location.toLowerCase().includes('online') ||
    workshop.location.toLowerCase().includes('self-paced') ||
    workshop.location.toLowerCase().includes('live online');

  // Format start date for schema in ISO 8601
  let startDate;

  // For "anytime" or self-paced courses, use current date
  if (
    workshop.date.toLowerCase().includes('anytime') ||
    workshop.date.toLowerCase().includes('join any') ||
    workshop.date.toLowerCase().includes('register anytime') ||
    workshop.date.toLowerCase().includes('none currently')
  ) {
    startDate = format(new Date(), "yyyy-MM-dd'T'HH:mm:ss'Z'");
  } else {
    const dateMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})/
    );

    const dateWithParenthesisMatch = workshop.date.match(
      /([A-Za-z]+)\s+(\d+)(?:[-–]\d+)?,\s+(\d{4})\s+\(/
    );

    if (dateMatch) {
      const [_, month, day, year] = dateMatch;
      const parsedDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
      startDate = isValid(parsedDate)
        ? format(parsedDate, "yyyy-MM-dd'T'HH:mm:ss'Z'")
        : format(new Date(), "yyyy-MM-dd'T'HH:mm:ss'Z'");
    } else if (dateWithParenthesisMatch) {
      const [_, month, day, year] = dateWithParenthesisMatch;
      const parsedDate = parse(
        `${month} ${day} ${year}`,
        'MMMM d yyyy',
        new Date()
      );
      startDate = isValid(parsedDate)
        ? format(parsedDate, "yyyy-MM-dd'T'HH:mm:ss'Z'")
        : format(new Date(), "yyyy-MM-dd'T'HH:mm:ss'Z'");
    } else {
      // Fallback to current date if we can't parse
      startDate = format(new Date(), "yyyy-MM-dd'T'HH:mm:ss'Z'");
    }
  }

  // Build the structured data object
  return {
    '@context': 'https://schema.org',
    '@type': 'Event',
    name: `${course.data.name} Training`,
    description: course.data.description,
    startDate: startDate,
    eventStatus: 'https://schema.org/EventScheduled',
    eventAttendanceMode: isVirtual
      ? 'https://schema.org/OnlineEventAttendanceMode'
      : 'https://schema.org/OfflineEventAttendanceMode',
    location: isVirtual
      ? {
          '@type': 'VirtualLocation',
          url: workshop.url,
        }
      : {
          '@type': 'Place',
          name: workshop.location,
          address: {
            '@type': 'PostalAddress',
            addressLocality: workshop.location,
          },
        },
    organizer: {
      '@type': 'Organization',
      name: 'Agile Pain Relief',
      url: Astro.site?.toString() ?? '',
    },
    offers: {
      '@type': 'Offer',
      url: workshop.url,
      availability: 'https://schema.org/InStock',
      price: priceValue,
      priceCurrency: priceCurrency,
      validFrom: format(new Date(), 'yyyy-MM-dd'),
    },
    performer: {
      '@type': 'Person',
      name: 'Mark Levison',
    },
    image: new URL(course.data.navigationImage.src, Astro.site).toString(),
  };
});
---

{
  eventsStructuredData.map((eventData) => (
    <script
      is:inline
      type="application/ld+json"
      set:html={JSON.stringify(eventData)}
    />
  ))
}

