import { defineCollection, reference } from 'astro:content';
import { z } from 'astro/zod';
import { glob } from 'astro/loaders';
import { createQuizSchema } from './lib/quiz-engine';

const blog = defineCollection({
  loader: glob({
    pattern: ['**/*.md', '**/*.mdx'],
    base: './src/content/blog',
  }),
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      excerpt: z.string().optional(),
      draft: z.boolean().optional(),
      date: z.string(),
      lastUpdated: z.string().optional(),
      coverImage: image().optional(),
      categories: z.array(reference('categories')).optional(),
    }),
});

const categories = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/categories' }),
  schema: z.object({
    title: z.string(),
    description: z.string().optional(),
  }),
});

const courses = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/courses' }),
  schema: ({ image }) =>
    z.object({
      name: z.string(),
      shortName: z.string(),
      description: z.string(),
      navigationDescription: z.string(),
      navigationImage: image(),
      ctaButton: z
        .object({
          text: z.string(),
          href: z.string(),
        })
        .optional(),
      hero: z.object({
        image: image(),
        imageAltText: z.string(),
        heading: z.string(),
        body: z.string(),
        button: z
          .object({
            text: z.string(),
            href: z.string(),
          })
          .optional(),
      }),
      courseHighlights: z
        .array(
          z.object({
            heading: z.string(),
            body: z.string(),
          })
        )
        .max(3),
      courseBadge: image(),
      whoShouldAttend: z.array(z.string()).optional(),

      workshops: z.object({
        heading: z.string(),
        body: z.string(),
        workshops: z.array(
          z.object({
            date: z.string(),
            location: z.string(),
            url: z.string(),
          })
        ),
      }),

      learningGoals: z.object({
        sectionTitle: z.string().optional(),
        heading: z.string(),
        goals: z.array(
          z.object({
            heading: z.string(),
            body: z.string(),
          })
        ),
      }),
      testimonials: z.object({
        heading: z.string(),
        body: z.string(),
      }),

      faqs: z.object({
        heading: z.string(),
        faqs: z.array(reference('faqs')),
      }),
    }),
});

const testimonials = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/testimonials' }),
  schema: z.object({
    name: z.string(),
    location: z.string(),
    courseType: reference('courses').optional(),
    priority: z.string().optional(),
  }),
});

const faqs = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/faqs' }),
  schema: z.object({
    question: z.string(),
  }),
});

const glossary = defineCollection({
  loader: glob({
    pattern: ['**/*.md', '**/*.mdx'],
    base: './src/content/glossary',
  }),
  schema: z.object({
    title: z.string(),
    draft: z.boolean().optional(),
    excerpt: z.string().optional(),
    date: z.string(),
    lastUpdated: z.string().optional(),
    relatedTerms: z.array(reference('glossary')).optional(),
    aliases: z.array(z.string()).optional(),
  }),
});

const pages = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    draft: z.boolean().optional(),
    includeBreadcrumbs: z.boolean().optional(),
    includeCoursesCTA: z.boolean().optional(),
    noIndex: z.boolean().optional(),
    registerButton: z
      .object({
        href: z.string(),
        label: z.string(),
        description: z.string(),
      })
      .optional(),
  }),
});

const seoPages = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/seoPages' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    draft: z.boolean().optional(),
    includeBreadcrumbs: z.boolean().optional(),
    includeCoursesCTA: z.boolean().optional(),
    noIndex: z.boolean().optional(),
    registerButton: z
      .object({
        href: z.string(),
        label: z.string(),
        description: z.string(),
      })
      .optional(),
  }),
});

// The engine schema covers quiz mechanics (questions, scoring, levels). APR's
// landing page wants additional marketing copy fields; extend the engine
// schema here rather than pushing site-specific concerns into the engine.
const quizzes = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/quizzes' }),
  schema: (ctx) =>
    createQuizSchema(ctx).extend({
      heroHeading: z.string().optional(),
      heroBody: z.string().optional(),
      // Label for the landing-page hero CTA and the stepper's intro "start"
      // button (kept in sync so both read the same). Defaults per quiz copy.
      heroButtonLabel: z.string().optional(),
      // Small print under the hero CTA. Per-quiz because it has to tell the
      // truth about when the email is asked for (see `capturePosition`).
      heroButtonNote: z.string().optional(),
      categoriesHeading: z.string().optional(),
      // Heading and chip icon on the "before you start" step that sits between
      // the cover and question 1.
      introHeading: z.string().optional(),
      introIcon: z.string().optional(),
      persuasion: z.string().optional(),
      // Checklist bullets shown under the persuasion block. Per-quiz because the
      // proof points differ (question count, "real studies", etc.).
      persuasionBullets: z.array(z.string()).optional(),
      // Copy on the email-capture step. Heading and body default to engine
      // wording that suits the quiz's `capturePosition`; override to say it in
      // the quiz's own voice.
      captureHeading: z.string().optional(),
      captureBody: z.string().optional(),
      // Label on the capture form's button. Distinct from `submitButtonLabel`
      // because on a start gate the capture button begins the quiz, while
      // `submitButtonLabel` ends it.
      captureButtonLabel: z.string().optional(),
      // Small print under the capture submit button (what the user opts into).
      captureFootnote: z.string().optional(),
      // Label for the button that finishes the quiz (e.g. "Show me my map").
      submitButtonLabel: z.string().optional(),
      // No cakemailFormUrl: the quiz capture is gated through Turnstile and POSTs
      // to /api/newsletter-signup (see GatedQuizStepper), not browser-direct to a
      // Cakemail form. The engine's built-in cakemailFormUrl path is unused here.
      submissionTags: z.array(z.string()).optional(),
      levelTagPrefix: z.string().optional(),
    }),
});

export const collections = {
  blog,
  testimonials,
  faqs,
  courses,
  glossary,
  pages,
  seoPages,
  categories,
  quizzes,
};

