/**
 * Minimal Corsizio API client, shared by the site's schedule sync
 * (scripts/corsizio-sync.ts) and the course-email CLI (email-automation/).
 *
 * The site itself never imports this: it reads the generated
 * shared/course-schedule.json instead, so a Corsizio outage can't break a
 * build. Only the two tools that talk to the API live here.
 *
 * Auth is a bearer token (the API Secret Access Key from Corsizio's Account ->
 * Integration Settings), stored as CORSIZIO in the repo-root .env. Callers pass
 * it in rather than reading the environment here, because the two callers load
 * their environment differently.
 *
 * Docs: https://help.corsizio.com/category/28-developer-api
 */

const API = 'https://api.corsizio.com/v1';

export interface CorsizioPrice {
  price: number;
  label?: string;
  description?: string;
  earlyPrice: number | null;
  earlyBefore: string | null;
}

/** Only the fields we consume; Corsizio returns considerably more. */
export interface CorsizioEvent {
  id: string;
  name: string;
  /** ISO 8601 UTC instant of the FIRST day's start. */
  startDate: string;
  /** ISO 8601 UTC instant of the LAST day's end. */
  endDate: string;
  /** Corsizio's own long-form label, e.g. "Thu, Sep 3, 2026, 9:00 AM EDT - ...". */
  displayDate: string;
  /** IANA timezone the event is run in, e.g. "America/Toronto". */
  timeZone: string;
  location?: string;
  priceFrom?: number;
  priceTo?: number;
  prices?: CorsizioPrice[];
  currency?: string;
  pageUrl: string;
  registrationCloseDate?: string | null;
  categories?: { id: string; label: string }[];
}

interface EventsListResponse {
  paging: { page: number; limit: number; count: number; more: boolean };
  list: CorsizioEvent[];
}

async function corsizioGet<T>(pathAndQuery: string, key: string): Promise<T> {
  const res = await fetch(`${API}${pathAndQuery}`, {
    headers: { Authorization: `Bearer ${key}` },
  });
  if (!res.ok) {
    throw new Error(
      `Corsizio GET ${pathAndQuery} failed: HTTP ${res.status} ${await res.text()}`
    );
  }
  return (await res.json()) as T;
}

/**
 * Fetch one event by id.
 *
 * Verified to work for events that have already run, which is what the
 * post-course email depends on. A DELETED event 404s (Corsizio does not
 * tombstone them), and so does a typo'd id: both surface as a thrown error,
 * which is the behaviour we want before anyone gets emailed.
 */
export async function fetchEventById(eventId: string, key: string): Promise<CorsizioEvent> {
  return corsizioGet<CorsizioEvent>(`/events/${eventId}`, key);
}

/** Every published event, all dates, oldest first. Follows pagination. */
export async function fetchPublishedEvents(key: string): Promise<CorsizioEvent[]> {
  const events: CorsizioEvent[] = [];
  let page = 1;
  for (;;) {
    const body = await corsizioGet<EventsListResponse>(
      `/events?status=published&limit=100&page=${page}&order=startDate&expand=filters`,
      key
    );
    events.push(...body.list);
    if (!body.paging.more) return events;
    page += 1;
  }
}

// --- Date helpers ---------------------------------------------------------
//
// startDate/endDate are UTC instants but the course runs in `timeZone`. Every
// label and day count has to be computed in that zone, or a 9am Toronto class
// can round onto the wrong calendar day.

/** Calendar parts of an instant, as seen in `timeZone`. */
export function partsIn(iso: string, timeZone: string) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    hour12: false,
  });
  const parts = Object.fromEntries(
    fmt.formatToParts(new Date(iso)).map((p) => [p.type, p.value])
  );
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
  };
}

/** Calendar days spanned, inclusive, counted in the event's timezone. */
export function countDays(startIso: string, endIso: string, timeZone: string): number {
  const s = partsIn(startIso, timeZone);
  const e = partsIn(endIso, timeZone);
  const startUtc = Date.UTC(s.year, s.month - 1, s.day);
  const endUtc = Date.UTC(e.year, e.month - 1, e.day);
  return Math.round((endUtc - startUtc) / 86_400_000) + 1;
}

/** Local calendar date of an instant in `timeZone`, as YYYY-MM-DD. */
export function localDate(iso: string, timeZone: string): string {
  const { year, month, day } = partsIn(iso, timeZone);
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

/** Daily class window as "HH:MM-HH:MM" (24h) in `timeZone`. */
export function localTimeRange(startIso: string, endIso: string, timeZone: string): string {
  const s = partsIn(startIso, timeZone);
  const e = partsIn(endIso, timeZone);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(s.hour)}:${pad(s.minute)}-${pad(e.hour)}:${pad(e.minute)}`;
}

