1	/**
2	 * Pull the course schedule from Corsizio and write shared/course-schedule.json.
3	 *
4	 * Corsizio is the source of truth for WHEN a public course runs and WHAT it
5	 * costs. This script is the only thing that talks to their API for listings;
6	 * everything downstream (course pages, the "Get Certified" block, JSON-LD, the
7	 * newsletter's Upcoming Courses list) reads the generated file.
8	 *
9	 * The generated file is committed on purpose. It lives in shared/, so writing
10	 * it triggers a Netlify rebuild on push, and a Corsizio outage can never take a
11	 * deploy down. It also gives us a git history of schedule changes.
12	 *
13	 *   npm run sync-courses            # write the file
14	 *   npm run sync-courses -- --dry-run   # print what would change, write nothing
15	 *
16	 * Needs CORSIZIO (the API secret access key) in the repo-root .env.
17	 */
18	
19	import fs from 'fs';
20	import path from 'path';
21	import { fileURLToPath } from 'url';
22	import {
23	  type CorsizioEvent,
24	  countDays,
25	  fetchPublishedEvents,
26	  partsIn,
27	} from '../shared/corsizio';
28	
29	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
30	const OUTPUT_PATH = path.join(ROOT, 'shared', 'course-schedule.json');
31	
32	// --- Corsizio category -> course ------------------------------------------
33	//
34	// Every Corsizio event carries exactly one category, and the category ids are
35	// stable, so this table is the whole mapping: no matching on event names, which
36	// change whenever Mark retitles a workshop.
37	//
38	// `slug` is the src/content/courses/ directory name. `null` means "real course,
39	// deliberately not a course-collection page" — currently only the AI Tsunami,
40	// which is a marketing page with its own hand-written schedule prose.
41	//
42	// A category id that is NOT in this table is reported loudly by the sync: it
43	// means a new kind of course exists in Corsizio and nothing on the site will
44	// show it until someone adds a row here.
45	
46	interface CourseMapping {
47	  slug: string | null;
48	  /** Display name for the newsletter's Upcoming Courses list. */
49	  name: string;
50	}
51	
52	const CATEGORY_TO_COURSE: Record<string, CourseMapping> = {
53	  '67e30b6100cd6ddccedcc2c1': {
54	    slug: 'certified-scrummaster-csm-training',
55	    name: 'Certified ScrumMaster (CSM)',
56	  },
57	  '67e4270400cd6ddccefef17c': {
58	    slug: 'certified-scrum-product-owner-cspo-training',
59	    name: 'Certified Scrum Product Owner (CSPO)',
60	  },
61	  '67e4271d00cd6ddccefef4db': {
62	    slug: 'advanced-certified-scrummaster-acsm-training',
63	    name: 'Advanced Certified ScrumMaster (A-CSM)',
64	  },
65	  '67fd4bae00cd6ddcceb14a06': {
66	    slug: 'certified-scrum-professional-scrummaster-csp-sm-training',
67	    name: 'Certified Scrum Professional - ScrumMaster (CSP-SM)',
68	  },
69	  '68f253e18289735f6334a11e': {
70	    slug: 'scrum-better-with-kanban',
71	    name: 'Scrum Better with Kanban',
72	  },
73	  // Only the Technical track is scheduled, so Corsizio has one CSD category and
74	  // it maps to the Technical page. The Nontechnical page therefore never gets
75	  // events and always renders the "contact us" placeholder, which is correct.
76	  '69cd8eb84fa9204f41054cc2': {
77	    slug: 'certified-scrum-developer-training-csd-technical',
78	    name: 'Certified Scrum Developer (CSD)',
79	  },
80	  '6a106e4c8bc748bdca8e91bc': {
81	    slug: null, // Surviving the AI Tsunami — a page, not a course collection entry
82	    name: 'Surviving the AI Tsunami',
83	  },
84	};
85	
86	// Corsizio labels every online event "In-person Online". Normalise to the
87	// wording the site has always used.
88	function normaliseLocation(raw: string | undefined): string {
89	  if (!raw) return 'Live Online';
90	  return /online|virtual/i.test(raw) ? 'Live Online' : raw;
91	}
92	
93	// --- Generated file shape -------------------------------------------------
94	
95	export interface ScheduledWorkshop {
96	  eventId: string;
97	  /** ISO 8601 UTC, first day's start. */
98	  startDate: string;
99	  /** ISO 8601 UTC, last day's end. */
100	  endDate: string;
101	  /** IANA timezone the course is run in. */
102	  timeZone: string;
103	  /** e.g. "August 11-14, 2026" */
104	  dateLabel: string;
105	  /** Daily start-end, e.g. "9:00 AM - 1:00 PM EDT" */
106	  timeLabel: string;
107	  /** Days spanned, inclusive. */
108	  numberOfDays: number;
109	  location: string;
110	  url: string;
111	  priceFrom: number;
112	  priceTo: number;
113	  currency: string;
114	  registrationCloseDate: string | null;
115	}
116	
117	interface CourseSchedule {
118	  /** Display name, for consumers with no access to the content collection. */
119	  name: string;
120	  workshops: ScheduledWorkshop[];
121	}
122	
123	interface ScheduleFile {
124	  generatedAt: string;
125	  courses: Record<string, CourseSchedule>;
126	}
127	
128	// --- Date formatting, in the event's own timezone -------------------------
129	//
130	// startDate/endDate are UTC instants; the course runs in `timeZone`. Every
131	// label and the day count must be computed in that zone, or a 9am Toronto class
132	// can round to the wrong calendar day.
133	
134	const MONTHS = [
135	  'January', 'February', 'March', 'April', 'May', 'June',
136	  'July', 'August', 'September', 'October', 'November', 'December',
137	];
138	
139	/** "August 11-14, 2026", "September 3, 2026", "August 31 - September 1, 2026" */
140	function buildDateLabel(startIso: string, endIso: string, timeZone: string): string {
141	  const s = partsIn(startIso, timeZone);
142	  const e = partsIn(endIso, timeZone);
143	
144	  if (s.year === e.year && s.month === e.month) {
145	    const days = s.day === e.day ? `${s.day}` : `${s.day}-${e.day}`;
146	    return `${MONTHS[s.month - 1]} ${days}, ${s.year}`;
147	  }
148	  if (s.year === e.year) {
149	    return `${MONTHS[s.month - 1]} ${s.day} - ${MONTHS[e.month - 1]} ${e.day}, ${s.year}`;
150	  }
151	  return `${MONTHS[s.month - 1]} ${s.day}, ${s.year} - ${MONTHS[e.month - 1]} ${e.day}, ${e.year}`;
152	}
153	
154	/** Timezone abbreviation as of a given instant, e.g. "EDT". */
155	function tzAbbrev(iso: string, timeZone: string): string {
156	  const fmt = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'short' });
157	  return fmt.formatToParts(new Date(iso)).find((p) => p.type === 'timeZoneName')?.value ?? '';
158	}
159	
160	function format12h(hour: number, minute: number): string {
161	  const period = hour < 12 ? 'AM' : 'PM';
162	  const h = hour % 12 === 0 ? 12 : hour % 12;
163	  return `${h}:${String(minute).padStart(2, '0')} ${period}`;
164	}
165	
166	/**
167	 * "9:00 AM - 1:00 PM EDT" — the daily class times.
168	 *
169	 * startDate carries the FIRST day's start and endDate the LAST day's end, so
170	 * for the courses we run (same hours every day) this is the daily schedule.
171	 * It would be wrong for an event whose days have different hours; Corsizio
172	 * models those with breakdownDates, which none of our courses use.
173	 */
174	function buildTimeLabel(startIso: string, endIso: string, timeZone: string): string {
175	  const s = partsIn(startIso, timeZone);
176	  const e = partsIn(endIso, timeZone);
177	  return `${format12h(s.hour, s.minute)} - ${format12h(e.hour, e.minute)} ${tzAbbrev(endIso, timeZone)}`;
178	}
179	
180	// --- Fetch ----------------------------------------------------------------
181	
182	/** Read CORSIZIO from the repo-root .env (a named pipe: read it exactly once). */
183	function loadKey(): string {
184	  const envPath = path.join(ROOT, '.env');
185	  let raw: string;
186	  try {
187	    raw = fs.readFileSync(envPath, 'utf-8');
188	  } catch (err) {
189	    throw new Error(`Could not read ${envPath}: ${String(err)}`);
190	  }
191	  for (const line of raw.split('\n')) {
192	    const trimmed = line.trim();
193	    if (!trimmed || trimmed.startsWith('#')) continue;
194	    const eq = trimmed.indexOf('=');
195	    if (eq === -1) continue;
196	    if (trimmed.slice(0, eq).trim() === 'CORSIZIO') {
197	      return trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
198	    }
199	  }

