old_iface = """export interface CourseConfig {
  type: string;
  date: string; // YYYY-MM-DD (start date)
  numberOfDays: number;
  duration?: string; // "HH:MM-HH:MM" (daily start-end, 24h). Default: "08:59-17:01"
  timezone?: string; // IANA timezone. Default: "America/Toronto"
  location?: string; // Default: "Virtual"
  muralLink: string;
  googleDocsFolder?: string;
  workbookUrl?: string; // Per-cohort override for the post-course workbook link; normally left unset (resolved by course type from workbook-urls.json)
  dropboxFolder?: string; // Legacy post-course materials link; used only for courses not yet moved to /materials/
  meetingInvite: MeetingInvite;
}"""

new_iface = '''/**
 * What is actually stored in courses/*.json.
 *
 * Deliberately holds NO dates. The cohort's schedule lives in Corsizio and is
 * resolved by `resolveCourseConfig` from `corsizioEventId`, so the date can
 * never drift out of step with what the site advertises and what students
 * registered for. What stays here is only the per-cohort material Corsizio has
 * never heard of: the Zoom meeting, the Mural board, the docs folders.
 */
export interface CourseConfigFile {
  type: string;
  /** Corsizio event id (the 24-hex id in the event's registration URL). */
  corsizioEventId: string;
  /**
   * Optional override of the daily class window, "HH:MM-HH:MM" (24h).
   *
   * Normally unset, so the times come from Corsizio and match what students
   * booked. Set it only when the calendar invite should deliberately differ:
   * CSM uses "08:59-17:01" so the invite brackets the 9-to-5 class by a minute
   * either side. Delete that line to adopt Corsizio's exact times.
   */
  duration?: string;
  timezone?: string; // IANA timezone. Defaults to the Corsizio event's own zone.
  location?: string; // Default: "Virtual"
  muralLink: string;
  googleDocsFolder?: string;
  workbookUrl?: string; // Per-cohort override for the post-course workbook link; normally left unset (resolved by course type from workbook-urls.json)
  dropboxFolder?: string; // Legacy post-course materials link; used only for courses not yet moved to /materials/
  meetingInvite: MeetingInvite;
}

/**
 * A cohort config with its Corsizio-derived schedule filled in. Everything
 * downstream (the derive* helpers, the calendar URL builders) takes this, so it
 * stays fully synchronous: exactly one network call happens, in
 * `resolveCourseConfig`, before any rendering.
 */
export interface CourseConfig extends CourseConfigFile {
  date: string; // YYYY-MM-DD (start date), in the event's timezone
  numberOfDays: number;
  duration: string; // "HH:MM-HH:MM" (daily start-end, 24h)
  timezone: string; // IANA timezone
}

/**
 * Resolve a cohort's schedule from Corsizio.
 *
 * Throws if the event is missing (deleted, cancelled, or a typo'd id) rather
 * than falling back to a stale local date, so a bad id is caught before anyone
 * is emailed. Same spirit as `assertWorkbookReachable` below.
 */
export async function resolveCourseConfig(file: CourseConfigFile): Promise<CourseConfig> {
  const key = process.env.CORSIZIO;
  if (!key) {
    throw new Error("CORSIZIO is not set in the repo-root .env; cannot resolve the course date.");
  }

  let event;
  try {
    event = await fetchEventById(file.corsizioEventId, key);
  } catch (err) {
    throw new Error(
      `Could not load Corsizio event ${file.corsizioEventId} for the ${file.type} cohort. ` +
        `If the course was cancelled or the id is wrong, fix courses/ before sending. ` +
        `(${err instanceof Error ? err.message : String(err)})`,
    );
  }

  const timezone = file.timezone ?? event.timeZone;
  console.log(
    `Corsizio ${file.type} ${file.corsizioEventId}: ${event.displayDate}`,
  );

  return {
    ...file,
    date: localDate(event.startDate, timezone),
    numberOfDays: countDays(event.startDate, event.endDate, timezone),
    duration: file.duration ?? localTimeRange(event.startDate, event.endDate, timezone),
    timezone,
  };
}'''

