import { resolve } from "path";''',
'''import { readFileSync } from "fs";
import { resolve } from "path";
import {
  countDays,
  fetchEventById,
  localDate,
  localTimeRange,
} from "../../shared/corsizio";''', 1)

# duration / timezone are now always resolved, so the defaults are dead code.
