2	// The site never imports this; it reads the generated course-schedule.json.
3	// Docs: https://help.corsizio.com/category/28-developer-api
4	
5	const API = 'https://api.corsizio.com/v1';
6	
7	export interface CorsizioPrice {
8	  price: number;
9	  label?: string;
10	  description?: string;
