33	interface EventsListResponse {
34	  paging: { page: number; limit: number; count: number; more: boolean };
35	  list: CorsizioEvent[];
36	}
37	
38	async function corsizioGet<T>(pathAndQuery: string, key: string): Promise<T> {
39	  const res = await fetch(`${API}${pathAndQuery}`, {
40	    headers: { Authorization: `Bearer ${key}` },
41	  });
42	  if (!res.ok) {
43	    throw new Error(
44	      `Corsizio GET ${pathAndQuery} failed: HTTP ${res.status} ${await res.text()}`
45	    );
46	  }
47	  return (await res.json()) as T;
48	}
49	
50	/** Works for past events too, which the post-course email needs. A deleted event 404s. */
51	export async function fetchEventById(eventId: string, key: string): Promise<CorsizioEvent> {
52	  return corsizioGet<CorsizioEvent>(`/events/${eventId}`, key);
53	}
54	
55	/** Every published event, all dates, oldest first. Follows pagination. */
56	export async function fetchPublishedEvents(key: string): Promise<CorsizioEvent[]> {
57	  const events: CorsizioEvent[] = [];
58	  let page = 1;
59	  for (;;) {
60	    const body = await corsizioGet<EventsListResponse>(
61	      `/events?status=published&limit=100&page=${page}&order=startDate&expand=filters`,
62	      key
63	    );
64	    events.push(...body.list);
65	    if (!body.paging.more) return events;
66	    page += 1;
67	  }
68	}
