70	// --- Date helpers ---------------------------------------------------------
71	// Dates are UTC instants; the course runs in `timeZone`. Computing labels and
72	// day counts in that zone, not UTC, is what keeps them on the right calendar day.
73	
74	/** Calendar parts of an instant, as seen in `timeZone`. */
75	export function partsIn(iso: string, timeZone: string) {
76	  const fmt = new Intl.DateTimeFormat('en-CA', {
77	    timeZone,
78	    year: 'numeric',
79	    month: 'numeric',
80	    day: 'numeric',
81	    hour: 'numeric',
82	    minute: 'numeric',
83	    hour12: false,
84	  });
85	  const parts = Object.fromEntries(
86	    fmt.formatToParts(new Date(iso)).map((p) => [p.type, p.value])
87	  );
88	  return {
89	    year: Number(parts.year),
90	    month: Number(parts.month),
91	    day: Number(parts.day),
92	    hour: Number(parts.hour) % 24,
93	    minute: Number(parts.minute),
94	  };
95	}
96	
97	/** Calendar days spanned, inclusive, counted in the event's timezone. */
98	export function countDays(startIso: string, endIso: string, timeZone: string): number {
99	  const s = partsIn(startIso, timeZone);
100	  const e = partsIn(endIso, timeZone);
101	  const startUtc = Date.UTC(s.year, s.month - 1, s.day);
102	  const endUtc = Date.UTC(e.year, e.month - 1, e.day);
103	  return Math.round((endUtc - startUtc) / 86_400_000) + 1;
104	}
105	
106	/** Local calendar date of an instant in `timeZone`, as YYYY-MM-DD. */
107	export function localDate(iso: string, timeZone: string): string {
108	  const { year, month, day } = partsIn(iso, timeZone);
109	  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
110	}
111	
112	/** Daily class window as "HH:MM-HH:MM" (24h) in `timeZone`. */
113	export function localTimeRange(startIso: string, endIso: string, timeZone: string): string {
114	  const s = partsIn(startIso, timeZone);
115	  const e = partsIn(endIso, timeZone);
116	  const pad = (n: number) => String(n).padStart(2, '0');
117	  return `${pad(s.hour)}:${pad(s.minute)}-${pad(e.hour)}:${pad(e.minute)}`;
118	}

